head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07231";
scwin.dts_ContentsDel = null;
scwin.dts_ContentsInfo = null;
scwin.dts_fileList = null;
scwin.dts_listClassCd = null;
scwin.upd_attachBinFiles = null;
scwin.upd_attachBinFiles2 = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — bbsList, param.modifyYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.dts_ContentsDel = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ContentsDel')) : $c.util.getComponent('dts_ContentsDel');
        scwin.dts_ContentsInfo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ContentsInfo')) : $c.util.getComponent('dts_ContentsInfo');
        scwin.dts_fileList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsFileList')) : $c.util.getComponent('dtsFileList');
        scwin.dts_listClassCd = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsListClassCd')) : $c.util.getComponent('dtsListClassCd');
        scwin.upd_attachBinFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachBinFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachBinFiles"]');
        scwin.upd_attachBinFiles2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachBinFiles2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachBinFiles2"]');
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07231.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_FileDown", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) === null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "btn_deleteAttachFile", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) === null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "if_attachFileNm_2", fn: function(){ return ((String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) === null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "if_attachFileNm_3", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) === null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_39", fn: function(){ return (!(String(((dma_pageContext.get("bbsList") ?? "")) === null ? '' : ((dma_pageContext.get("bbsList") ?? ""))).length === 0)); } }, { id: "c_when_96", fn: function(){ return ((String(((dma_pageContext.get("bbsList") ?? "")) === null ? '' : ((dma_pageContext.get("bbsList") ?? ""))).length === 0) && (String(((dma_pageContext.get("modifyYn") ?? "")) === null ? '' : ((dma_pageContext.get("modifyYn") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent('dlt_bbsList').setCellData(0, 'wrtrNm', $c.session.getUserInfo("empNm"));
        $c.util.getComponent('dlt_bbsList').setCellData(0, 'wrtrEmail', js_email);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07231.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_changePage, tx_fn_register) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

