/**
 * @method
 * @name tx_script_dts_ContentsInfo
 * @description script dts Contents Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_ContentsInfo = async function () {
    $c.util.getComponent("dma_scriptDts_ContentsInfoReq").set("messageId", "LIST_INVSTG_BBS_INFO_INOUT");
    const sbmOptions = {
        id: "tx_script_dts_ContentsInfo",
        method: "post",
        action: "/gauceSystemierAdaptor.do",
        ref: "dma_scriptDts_ContentsInfoReq",
        target: "dts_ContentsInfo=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_ContentsInfo_onloaderror'] === 'function') ? scwin['dts_ContentsInfo_onloaderror'] : (typeof scwin['dts_ContentsInfo_onfail'] === 'function') ? scwin['dts_ContentsInfo_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_ContentsInfo_onloadcompleted'] === 'function') ? scwin['dts_ContentsInfo_onloadcompleted'] : ((typeof scwin['dts_ContentsInfo_onsuccess'] === 'function') ? scwin['dts_ContentsInfo_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_ContentsInfo'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07231.tx_script_dts_ContentsInfo" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

