/**
 * @method
 * @name tx_fn_goList
 * @description go List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goList = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
